import onnx, onnxruntime as ort, numpy as np
from onnx import helper, TensorProto
shape=[10,10,30,30]; entries=[]
for v in range(3):
 entries += [((0,0,v,v),1.),((0,0,v+4,v),1.),((2,1,v,v),1.),((2,1,v+4,v),1.),((2,5,3,v),-1.)]
entries=sorted(entries,key=lambda x:np.ravel_multi_index(x[0],shape))
flat=[np.ravel_multi_index(i,shape) for i,v in entries]; vals=[v for i,v in entries]
sp=helper.make_sparse_tensor(helper.make_tensor('W',TensorProto.FLOAT,[15],vals),helper.make_tensor('Wi',TensorProto.INT64,[15],flat),shape)
g=helper.make_graph([helper.make_node('Einsum',['input','W'],['output'],equation='bchw,ocwv->bohv',name='output')],'g',[helper.make_tensor_value_info('input',TensorProto.FLOAT,[1,10,30,30])],[helper.make_tensor_value_info('output',TensorProto.FLOAT,[1,10,30,30])],sparse_initializer=[sp])
m=helper.make_model(g,ir_version=10,opset_imports=[helper.make_opsetid('',12)])
for full in [False,True]:
 try: onnx.checker.check_model(m,full_check=full); print('checker',full,'OK')
 except Exception as e: print('checker',full,'FAIL',type(e).__name__,e)
try:
 sm=onnx.shape_inference.infer_shapes(m,strict_mode=True); print('infer OK',onnx.helper.printable_graph(sm.graph))
except Exception as e: print('infer FAIL',type(e).__name__,e)
PY"

