/bin/bash -lc "~/.venv/bin/python - <<'PY'
import onnx, onnxruntime as ort, numpy as np
from onnx import helper, TensorProto
shape=[10,10,30,30]; entries=[]
for v in range(3): entries += [((0,0,v,v),1.),((0,0,v+4,v),1.),((2,1,v,v),1.),((2,1,v+4,v),1.),((2,5,3,v),-1.)]
entries=sorted(entries,key=lambda x:np.ravel_multi_index(x[0],shape))
sp=helper.make_sparse_tensor(helper.make_tensor('W',TensorProto.FLOAT,[15],[v for _,v in entries]),helper.make_tensor('Wi',TensorProto.INT64,[15],[np.ravel_multi_index(i,shape) for i,_ in entries]),shape)
for placement in ['value_info','input']:
 vi=helper.make_tensor_value_info('W',TensorProto.FLOAT,shape)
 kwargs={'value_info':[vi]} if placement=='value_info' else {}
 inputs=[helper.make_tensor_value_info('input',TensorProto.FLOAT,[1,10,30,30])]+([vi] if placement=='input' else [])
 g=helper.make_graph([helper.make_node('Einsum',['input','W'],['output'],equation='bchw,ocwv->bohv',name='output')],'g',inputs,[helper.make_tensor_value_info('output',TensorProto.FLOAT,[1,10,30,30])],sparse_initializer=[sp],**kwargs)
 m=helper.make_model(g,ir_version=10,opset_imports=[helper.make_opsetid('',12)])
 try: onnx.checker.check_model(m,full_check=True); print(placement,'full OK')
 except Exception as e: print(placement,'full FAIL',type(e).__name__,e)
 try: print('ORT',ort.InferenceSession(m.SerializeToString(),providers=['CPUExecutionProvider']).get_inputs())
 except Exception as e: print('ORT FAIL',e)
PY"

