from onnx import defs
latest={}
for s in defs.get_all_schemas_with_history():
 if s.domain=='' and (s.name not in latest or s.since_version>latest[s.name].since_version): latest[s.name]=s
for n,s in sorted(latest.items()):
 req=sum(i.option.name=='Single' for i in s.inputs)
 if len(s.inputs)<=3 and req<=1 and len(s.outputs)>=1:
  attrs=','.join(sorted(s.attributes))
  print(f'{n:28} in={len(s.inputs)} out={len(s.outputs)} attrs={attrs}')
